sysevent_script_action.script:
try {

    var eventstatus = event.parm1.toString();
    var widgetInboundRecord = event.parm2.toString();


    switch (eventstatus) {

        case 'AUTOMATED_QUERY':
            new x_hsb11_mss_taskiz.MSSTaskizeUtils().createCaseforAutomatedQueries(widgetInboundRecord);
            break;

        case 'BUBBLE_UPDATED':
            new x_hsb11_mss_taskiz.MSSTaskizeUtils().createCaseforManualIncomingQueries(widgetInboundRecord);
            break;

        case 'CONTENT_UPDATED':
            new x_hsb11_mss_taskiz.MSSTaskizeUtils().updateContentDataOnCase(widgetInboundRecord);
            break;

        case 'PARTICIPANT_UPDATED':
            new x_hsb11_mss_taskiz.MSSTaskizeUtils().updateParticipantDataOnCase(widgetInboundRecord);
            break;

        case 'RESOURCE_FILE_UPDATED':
            new x_hsb11_mss_taskiz.MSSTaskizeUtils().updateFileOnCase(widgetInboundRecord);
            break;

        case 'ADD_PARTICIPANT':
            new x_hsb11_mss_taskiz.MSSTaskizeUtils().updateAddPartyParticipantCase(widgetInboundRecord);
            break;

        case 'BUBBLE_CREATE_WITH_ATTRIBUTE':
            new x_hsb11_mss_taskiz.MSSTaskizeUtils().updateBubbleIDOnCase(widgetInboundRecord);
            break;

        case 'BUBBLE_UPDATE':
            new x_hsb11_mss_taskiz.MSSTaskizeUtils().updatCaseState(widgetInboundRecord);
            break;

        case 'ATTRIBUTE_UPDATE':
            new x_hsb11_mss_taskiz.MSSTaskizeUtils().errorLogForContentandAttributeUpdate(widgetInboundRecord, 'ATTRIBUTE_UPDATE'); //logging error message for attribute update
            break;

        case 'POST_CONTENT':
            new x_hsb11_mss_taskiz.MSSTaskizeUtils().errorLogForContentandAttributeUpdate(widgetInboundRecord, 'POST_CONTENT'); //logging error message for attribute update
            break;


        default:
            gs.info('Invalid Taskize Event Received');


    }

} catch (e) {
    gs.info('Script Action - MSS Create Taskize Case: Unknown exception while processing Taskize case creation:' + e.message);
}
